dict.string:
SUBQUERY(extensionItems, $item,
  SUBQUERY($item.attachments, $attachment,
    ANY $attachment.registeredTypeIdentifiers == "com.yjmeqt.attn.share-origin" OR
    ANY $attachment.registeredTypeIdentifiers == "com.yjmeqt.attn.shared-url" OR
    ANY $attachment.registeredTypeIdentifiers == "com.yjmeqt.attn.shared-image"
  ).@count > 0
).@count == 0 AND SUBQUERY(extensionItems, $item,
  SUBQUERY($item.attachments, $attachment,
    ANY $attachment.registeredTypeIdentifiers UTI-CONFORMS-TO "public.url" OR
    ANY $attachment.registeredTypeIdentifiers UTI-CONFORMS-TO "public.text" OR
    ANY $attachment.registeredTypeIdentifiers UTI-CONFORMS-TO "public.image"
  ).@count > 0
).@count > 0
